.dp-archive-gallery {
  padding: clamp(64px, 8vw, 104px) 0;
  background: #F5F7F8;
}

.dp-archive-gallery__inner {
  width: min(1240px, calc(100% - 40px));
  margin: 0 auto;
}

.dp-archive-gallery__head {
  max-width: 760px;
  margin-bottom: 34px;
}

.dp-archive-gallery__head span {
  display: block;
  margin-bottom: 10px;
  color: #D7DDE0;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.dp-archive-gallery__head h2 {
  margin: 0;
  color: #002949;
  font-size: clamp(30px, 4vw, 52px);
  line-height: 1.04;
}

.dp-archive-gallery__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 16px;
}

.dp-archive-gallery figure {
  position: relative;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  background: #FFFFFF;
  box-shadow: 0 12px 30px rgba(0,41,73,.10);
}

.dp-archive-gallery img {
  display: block;
  width: 100%;
  height: 280px;
  object-fit: cover;
}

.dp-archive-gallery figcaption {
  padding: 14px 16px;
  color: #002949;
  font-size: 12px;
  line-height: 1.45;
  font-weight: 800;
}


@media (max-width: 900px) {
  .dp-archive-gallery__grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

}

@media (max-width: 560px) {
  .dp-archive-gallery__grid {
    grid-template-columns: 1fr;
  }

  .dp-archive-gallery img {
    height: 240px;
  }

}
